actuate.code:
def actuate(sdk, action, ticks):
    state = sdk.get_state()
    budget = min(ticks, remaining(state))
    if budget > 0 and not opened(state):
        sdk.step_raw(action, steps=budget)
    return sdk.get_state()

angle.code:
def angle(state, name):
    value = state[name]
    return 0.0 if value is None else value

bounded_move.code:
def bounded_move(sdk, target, yaw, grip, limit, tolerance):
    state = sdk.get_state()
    budget = min(limit, steps_remaining(state))
    if budget > 0 and not door_open(state):
        sdk.move_to(
            target,
            yaw=yaw,
            gripper=grip,
            max_steps=budget,
            tol=tolerance,
        )
    return sdk.get_state()

door_open.code:
def door_open(state):
    hinge = state["hinge_qpos"]
    return hinge is not None and hinge > 0.30

