opening_tangent.code:
def opening_tangent(state):
    handle = state["objects"]["handle"]["pos"]
    door = state["objects"]["door"]["pos"]
    radial = [handle[0] - door[0], handle[1] - door[1], 0.0]
    if vector_norm(radial) < 0.025:
        yaw = state["objects"]["door"]["yaw"]
        radial = [cos(yaw), sin(yaw), 0.0]
    return unit_vector([-radial[1], radial[0], 0.0], [1.0, 0.0, 0.0])

servo.code:
def servo(sdk, target, rotation, grip=1.0):
    state = sdk.get_state()
    if remaining(state) > 0 and not opened(state):
        translation = [
            (target[i] - state["eef_pos"][i]) / 0.05
            for i in range(3)
        ]
        magnitude = norm(translation)
        if magnitude > 0.65:
            translation = [value * 0.65 / magnitude for value in translation]
        sdk.step_raw(translation + list(rotation) + [grip], steps=1)
    return sdk.get_state()

unit_vector.code:
def unit_vector(v, fallback):
    length = vector_norm(v)
    if length < 0.00001:
        return list(fallback)
    return vector_scale(v, 1.0 / length)

aligned_grasp_yaw.code:
def aligned_grasp_yaw(cube_yaw, eef_yaw):
    period = pi / 2.0
    return cube_yaw + round((eef_yaw - cube_yaw) / period) * period

lift_is_stable.code:
def lift_is_stable(sdk, resting_height, minimum_lift):
    state = sdk.get_state()
    cube = state["objects"]["cube"]["pos"]
    if cube[2] - resting_height < minimum_lift:
        return False

    offset = [
        cube[0] - state["eef_pos"][0],
        cube[1] - state["eef_pos"][1],
        cube[2] - state["eef_pos"][2],
    ]

    for check in range(3):
        if remaining_steps(sdk.get_state()) < 5:
            return False
        actuate_budgeted(sdk, "close", 5)
        state = sdk.get_state()
        cube = state["objects"]["cube"]["pos"]
        eef = state["eef_pos"]
        drift = sqrt(sum(
            (cube[axis] - eef[axis] - offset[axis]) ** 2
            for axis in range(3)
        ))
        if cube[2] - resting_height < minimum_lift:
            return False
        if drift > 0.025 or distance_xy(cube, eef) > 0.055:
            return False

    return True

budget.code:
def budget(sdk):
    state = sdk.get_state()
    return max(0, min(400, state["max_steps"]) - state["steps_used"])

grip.code:
def grip(sdk, action, steps, reserve=0):
    count = min(steps, max(0, budget(sdk) - reserve))
    if count > 0:
        sdk.set_gripper(action, steps=count)

xy_error.code:
def xy_error(state):
    pos = state["objects"]["nut"]["pos"]
    goal = state["goal_pos"]
    return hypot(pos[0] - goal[0], pos[1] - goal[1])

actuate_bounded.code:
def actuate_bounded(sdk, action, steps=12):
    budget = min(steps, remaining_steps(sdk))
    if budget > 0:
        return sdk.set_gripper(action, steps=budget)
    return None

grasp_offset.code:
def grasp_offset(state):
    return [
        state["eef_pos"][i] - state["objects"]["can"]["pos"][i]
        for i in range(3)
    ]

move_bounded.code:
def move_bounded(sdk, target, gripper, steps=40, tolerance=0.018, yaw=None):
    budget = min(steps, remaining_steps(sdk))
    if budget <= 0:
        return {"reached": False}
    return sdk.move_to(
        target, yaw=yaw, gripper=gripper,
        max_steps=budget, tol=tolerance
    )

remaining_steps.code:
def remaining_steps(sdk):
    state = sdk.get_state()
    return max(0, min(400, state["max_steps"]) - state["steps_used"])
